"use client";

import { type ComponentPropsWithoutRef, forwardRef } from "react";
import { ContextMenu as Base } from "@base-ui/react/context-menu";
import { cn } from "@/lib/utils";
import { useContextMenuContext } from "./context-menu-state";

export type ContextMenuItemProps = ComponentPropsWithoutRef<typeof Base.Item> & {
  variant?: "default" | "destructive";
};

/** An action. Choosing it closes the menu; the app performs the work in onClick. */
export const ContextMenuItem = forwardRef<HTMLDivElement, ContextMenuItemProps>(function ContextMenuItem(
  { className, variant = "default", ...props },
  ref,
) {
  return (
    <Base.Item
      ref={ref}
      data-variant={variant}
      className={cn(
        "relative flex cursor-pointer select-none items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-none transition-colors data-[disabled]:pointer-events-none data-[highlighted]:text-accent-foreground data-[disabled]:opacity-50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0 [&_svg]:text-muted-foreground",
        variant === "destructive" &&
          "text-destructive data-[highlighted]:text-destructive [&_svg]:text-destructive",
        className,
      )}
      {...(props as ComponentPropsWithoutRef<typeof Base.Item>)}
    />
  );
});

export const ContextMenuGroup = Base.Group;

export const ContextMenuGroupLabel = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<typeof Base.GroupLabel>>(
  function ContextMenuGroupLabel({ className, ...props }, ref) {
    return (
      <Base.GroupLabel
        ref={ref}
        className={cn("px-2 py-1.5 text-xs font-medium text-muted-foreground", className)}
        {...(props as ComponentPropsWithoutRef<typeof Base.GroupLabel>)}
      />
    );
  },
);

export const ContextMenuSeparator = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<typeof Base.Separator>>(
  function ContextMenuSeparator({ className, ...props }, ref) {
    return <Base.Separator ref={ref} className={cn("-mx-1 my-1 h-px bg-border", className)} {...(props as ComponentPropsWithoutRef<typeof Base.Separator>)} />;
  },
);

/** A shortcut hint shown at the end of an item. It does not register the shortcut. */
export const ContextMenuShortcut = forwardRef<HTMLSpanElement, ComponentPropsWithoutRef<"span">>(function ContextMenuShortcut({ className, ...props }, ref) {
  return <span ref={ref} className={cn("ml-auto pl-4 text-xs tracking-widest text-muted-foreground", className)} {...props} />;
});

/** State of the nearest ContextMenu, for building your own parts. */
export function useContextMenu() {
  const { open, disabled } = useContextMenuContext("useContextMenu");
  return { open, disabled };
}

"use client";

import { useSharedHighlight, usePhoneMenu } from "./context-menu-responsive";
import { cn } from "@/lib/utils";
import { type TransitionEvent, type ComponentPropsWithoutRef, useState, forwardRef } from "react";
import { ContextMenu as Base } from "@base-ui/react/context-menu";
import { useContextMenuContext } from "./context-menu-state";

/**
 * Open motion: the popup grows from the corner it opened at, widening and lengthening
 * together while fading in. The corner follows the side and alignment Base UI picks
 * after flipping to stay on screen. The clip stops exactly at the popup's edge so the
 * growth is visible to the end, then is removed (data-revealed) so the outline and
 * shadow outside that edge show. Closing fades out.
 */
export const reveal = cn(
  "[clip-path:inset(0)] transition-[clip-path,opacity] duration-300 ease-[cubic-bezier(0.33,1,0.68,1)] motion-reduce:transition-none",
  "data-[revealed]:[clip-path:none] data-[starting-style]:opacity-0 data-[ending-style]:opacity-0 data-[ending-style]:duration-150",
  "data-[starting-style]:[clip-path:inset(0_100%_100%_0)]",
  "data-[side=top]:data-[starting-style]:[clip-path:inset(100%_100%_0_0)]",
  "data-[align=end]:data-[starting-style]:[clip-path:inset(0_0_100%_100%)]",
  "data-[side=top]:data-[align=end]:data-[starting-style]:[clip-path:inset(100%_0_0_100%)]",
);

/** Marks the popup revealed once its clip transition ends, which lifts the clip. */
export const markRevealed = (event: TransitionEvent<HTMLDivElement>) => {
  if (event.target === event.currentTarget && event.propertyName === "clip-path" && !event.currentTarget.hasAttribute("data-ending-style")) {
    event.currentTarget.setAttribute("data-revealed", "");
  }
};

export type ContextMenuContentProps = ComponentPropsWithoutRef<typeof Base.Popup> & {
  /** Where the popup is portalled. Defaults to document.body. */
  container?: HTMLElement | null;
  positionMethod?: "absolute" | "fixed";
  collisionPadding?: number;
  /** Styles the shared highlight that slides between items. It carries the item's data-variant. */
  highlightClassName?: string;
  /** Visible dismissal action on phones; replace for localization. */
  cancelLabel?: string;
};

export const ContextMenuContent = forwardRef<HTMLDivElement, ContextMenuContentProps>(function ContextMenuContent(
  { className, container, positionMethod, collisionPadding = 8, highlightClassName, cancelLabel = "Cancel", onTransitionEnd, children, ...props },
  ref,
) {
  const { animated, focusFirstRef } = useContextMenuContext("ContextMenuContent");
  const [popup, setPopup] = useState<HTMLDivElement | null>(null);
  const highlight = useSharedHighlight(popup);
  const phone = usePhoneMenu();

  return (
    <Base.Portal container={container ?? undefined}>
      {phone && <Base.Backdrop className="fixed inset-0 z-50 bg-black/40" />}
      <Base.Positioner positionMethod={positionMethod} collisionPadding={collisionPadding} className="z-50 outline-none"
        style={phone ? { position: "fixed", top: "auto", bottom: 0, left: 0, right: 0, width: "100%", transform: "none" } : undefined}>
        <Base.Popup
          onTransitionEnd={(event) => {
            onTransitionEnd?.(event);
            if (animated) markRevealed(event);
          }}
          ref={(node) => {
            if (typeof ref === "function") ref(node);
            else if (ref) ref.current = node;
            setPopup(node);
            // A keyboard-opened menu starts on its first available action.
            if (node && (phone || focusFirstRef.current)) {
              focusFirstRef.current = false;
              requestAnimationFrame(() => phone ? node.focus() : node.querySelector<HTMLElement>('[role="menuitem"]:not([data-disabled])')?.focus());
            }
          }}
          className={cn(
            "relative min-w-48 origin-[var(--transform-origin)] overflow-hidden rounded-md border border-border bg-popover p-1 text-popover-foreground shadow-md outline-none",
            phone && "max-h-[80dvh] w-full overflow-y-auto rounded-t-2xl rounded-b-none p-4 pb-[max(1rem,env(safe-area-inset-bottom))]",
            animated && (phone ? "transition-[transform,opacity] duration-200 ease-out data-[starting-style]:translate-y-full data-[ending-style]:translate-y-full data-[starting-style]:opacity-0 data-[ending-style]:opacity-0 motion-reduce:transition-none" : reveal),
            className,
          )}
          {...(props as ComponentPropsWithoutRef<typeof Base.Popup>)}
        >
          <span
            aria-hidden
            data-slot="highlight"
            data-variant={highlight?.variant}
            data-visible={highlight?.visible ? "" : undefined}
            className={cn(
              "pointer-events-none absolute rounded-sm bg-accent opacity-0 data-[visible]:opacity-100 data-[variant=destructive]:bg-destructive/10",
              animated && highlight?.slide && "transition-[top,height,width,opacity,background-color] duration-150 ease-out motion-reduce:transition-none",
              animated && !highlight?.slide && "transition-opacity duration-100 motion-reduce:transition-none",
              highlightClassName,
            )}
            style={highlight ? { top: highlight.top, left: highlight.left, width: highlight.width, height: highlight.height } : undefined}
          />
          {children}
          {phone && <Base.Item className="relative mt-3 flex min-h-11 items-center justify-center rounded-lg border border-border px-4 text-sm font-medium outline-none data-[highlighted]:bg-accent">{cancelLabel}</Base.Item>}
        </Base.Popup>
      </Base.Positioner>
    </Base.Portal>
  );
});

"use client";

import { useState, useEffect, useSyncExternalStore } from "react";

const query = "(max-width: 639px)";
const phoneSnapshot = () => typeof window.matchMedia === "function" && window.matchMedia(query).matches;
const serverSnapshot = () => false;
const subscribe = (notify: () => void) => {
  if (typeof window.matchMedia !== "function") return () => {};
  const media = window.matchMedia(query);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};

/** Keeps SSR deterministic, then adapts the open menu to the current viewport. */
export function usePhoneMenu() {
  return useSyncExternalStore(subscribe, phoneSnapshot, serverSnapshot);
}

export type Highlight = { top: number; left: number; width: number; height: number; variant?: string; visible: boolean; slide: boolean };

/**
 * One highlight for the whole menu. It follows Base UI's data-highlighted item, sliding across
 * separators and groups instead of each item lighting up on its own.
 */
export function useSharedHighlight(popup: HTMLElement | null) {
  const [highlight, setHighlight] = useState<Highlight | null>(null);
  useEffect(() => {
    if (!popup) return;
    const update = () => {
      const item = popup.querySelector<HTMLElement>('[role="menuitem"][data-highlighted]');
      setHighlight((previous) =>
        item
          ? {
              top: item.offsetTop,
              left: item.offsetLeft,
              width: item.offsetWidth,
              height: item.offsetHeight,
              variant: item.dataset.variant,
              visible: true,
              // Slide only from one item to another; the first highlight appears in place.
              slide: !!previous?.visible,
            }
          : previous && { ...previous, visible: false },
      );
    };
    const observer = new MutationObserver(update);
    observer.observe(popup, { subtree: true, attributes: true, attributeFilter: ["data-highlighted"] });
    update();
    return () => observer.disconnect();
  }, [popup]);
  return highlight;
}

"use client";

import { type MutableRefObject, createContext, useContext, type ReactNode, useState, useRef } from "react";
import { ContextMenu as Base } from "@base-ui/react/context-menu";

export type ContextMenuContextValue = {
  open: boolean;
  disabled: boolean;
  animated: boolean;
  targetRef: MutableRefObject<HTMLDivElement | null>;
  /** Opens the menu at a point, through the same path as a right click. */
  openAt: (x: number, y: number, fromKeyboard: boolean) => void;
  focusFirstRef: MutableRefObject<boolean>;
};

export const ContextMenuContext = createContext<ContextMenuContextValue | null>(null);

export function useContextMenuContext(part: string) {
  const context = useContext(ContextMenuContext);
  if (!context) throw new Error(`<${part}> must be used inside <ContextMenu>.`);
  return context;
}

/** Events we dispatch ourselves, so the keyboard handling below leaves them alone. */
export const synthetic = new WeakSet<Event>();

/**
 * Turns off text selection on the page while a finger holds the target, so a long
 * press opens the menu instead of also selecting nearby text (iOS starts both).
 * Returns a function that restores the previous setting.
 */
export function suspendTextSelection() {
  const style = document.documentElement.style;
  const previous = [style.userSelect, style.webkitUserSelect];
  style.userSelect = "none";
  style.webkitUserSelect = "none";
  return () => {
    [style.userSelect, style.webkitUserSelect] = previous;
  };
}

/** Bottom-left corner of an element: where a keyboard- or button-opened menu appears. */
export const cornerOf = (element: Element) => {
  const rect = element.getBoundingClientRect();
  return { x: rect.left, y: rect.bottom };
};

/** A contextmenu event the browser raised for the menu key or Shift+F10 rather than a pointer. */
export const isKeyboardEvent = (event: MouseEvent) => {
  const pointerType = (event as PointerEvent).pointerType;
  return pointerType === "" || (pointerType === undefined && event.button !== 2 && event.clientX === 0 && event.clientY === 0);
};

export type ContextMenuProps = {
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Leaves the browser's own menu in place and disables the button. */
  disabled?: boolean;
  /** Open and close transitions. Reduced motion is always honored. */
  motion?: boolean;
  children?: ReactNode;
};

export function ContextMenu({ open: openProp, defaultOpen = false, onOpenChange, disabled = false, motion = true, children }: ContextMenuProps) {
  const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen);
  const open = openProp ?? uncontrolledOpen;
  const targetRef = useRef<HTMLDivElement | null>(null);
  const focusFirstRef = useRef(false);

  const openAt = (x: number, y: number, fromKeyboard: boolean) => {
    const event = new MouseEvent("contextmenu", { bubbles: true, cancelable: true, clientX: x, clientY: y, button: 2 });
    synthetic.add(event);
    focusFirstRef.current = fromKeyboard;
    targetRef.current?.dispatchEvent(event);
  };

  return (
    <ContextMenuContext.Provider value={{ open, disabled, animated: motion, targetRef, openAt, focusFirstRef }}>
      <Base.Root
        open={open}
        disabled={disabled}
        onOpenChange={(next) => {
          if (openProp === undefined) setUncontrolledOpen(next);
          onOpenChange?.(next);
        }}
      >
        {children}
      </Base.Root>
    </ContextMenuContext.Provider>
  );
}

"use client";

import { type ComponentPropsWithoutRef, forwardRef, useRef, useEffect, type KeyboardEvent, type TouchEvent as ReactTouchEvent, type MouseEvent as ReactMouseEvent } from "react";
import { useContextMenuContext, cornerOf, suspendTextSelection, synthetic, isKeyboardEvent } from "./context-menu-state";
import { ContextMenu as Base } from "@base-ui/react/context-menu";
import { cn } from "@/lib/utils";

export type ContextMenuTargetProps = ComponentPropsWithoutRef<"div">;

/** The area that opens the menu on right click, long press, the menu key or Shift+F10. */
export const ContextMenuTarget = forwardRef<HTMLDivElement, ContextMenuTargetProps>(function ContextMenuTarget(
  { className, onKeyDown, onContextMenuCapture, onTouchStart, onTouchEnd, onTouchCancel, ...props },
  ref,
) {
  const { open, disabled, targetRef, openAt } = useContextMenuContext("ContextMenuTarget");
  const restoreSelection = useRef<(() => void) | null>(null);
  const endTouch = () => {
    restoreSelection.current?.();
    restoreSelection.current = null;
    // If the press opened the menu, clear any selection it started before selection was suspended.
    if (open) window.getSelection()?.removeAllRanges();
  };
  useEffect(() => () => restoreSelection.current?.(), []);

  const openFromKeyboard = () => {
    const focused = document.activeElement;
    const anchor = focused && targetRef.current?.contains(focused) ? focused : targetRef.current;
    if (!anchor) return;
    const { x, y } = cornerOf(anchor);
    openAt(x, y, true);
  };

  return (
    <Base.Trigger
      ref={(node) => {
        targetRef.current = node;
        if (typeof ref === "function") ref(node);
        else if (ref) ref.current = node;
      }}
      data-disabled={disabled ? "" : undefined}
      className={cn("outline-none", className)}
      onKeyDown={(event: KeyboardEvent<HTMLDivElement>) => {
        onKeyDown?.(event);
        if (disabled || event.defaultPrevented) return;
        if (event.key === "ContextMenu" || (event.shiftKey && event.key === "F10")) {
          event.preventDefault();
          openFromKeyboard();
        }
      }}
      onTouchStart={(event: ReactTouchEvent<HTMLDivElement>) => {
        onTouchStart?.(event);
        if (!disabled && !restoreSelection.current) restoreSelection.current = suspendTextSelection();
      }}
      onTouchEnd={(event: ReactTouchEvent<HTMLDivElement>) => {
        onTouchEnd?.(event);
        if (restoreSelection.current) endTouch();
      }}
      onTouchCancel={(event: ReactTouchEvent<HTMLDivElement>) => {
        onTouchCancel?.(event);
        if (restoreSelection.current) endTouch();
      }}
      onContextMenuCapture={(event: ReactMouseEvent<HTMLDivElement>) => {
        onContextMenuCapture?.(event);
        // Browsers anchor keyboard-raised menus at the page corner; reopen at the focused element instead.
        if (disabled || synthetic.has(event.nativeEvent) || !isKeyboardEvent(event.nativeEvent)) return;
        event.preventDefault();
        event.stopPropagation();
        openFromKeyboard();
      }}
      {...props}
    />
  );
});

export type ContextMenuButtonProps = ComponentPropsWithoutRef<"button">;

/** A visible button with the same actions, for touch, keyboard and discoverability. */
export const ContextMenuButton = forwardRef<HTMLButtonElement, ContextMenuButtonProps>(function ContextMenuButton(
  { className, children, onClick, onPointerDown, "aria-label": ariaLabel = "More actions", ...props },
  ref,
) {
  const { open, disabled, openAt } = useContextMenuContext("ContextMenuButton");
  // The press that dismisses an open menu should not reopen it.
  const wasOpen = useRef(false);

  return (
    <button
      ref={ref}
      type="button"
      aria-haspopup="menu"
      aria-expanded={open}
      aria-label={children ? undefined : ariaLabel}
      disabled={disabled}
      data-state={open ? "open" : "closed"}
      className={cn(
        "inline-flex size-8 shrink-0 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:bg-accent focus-visible:text-accent-foreground disabled:pointer-events-none disabled:opacity-50 data-[state=open]:bg-accent data-[state=open]:text-accent-foreground",
        className,
      )}
      onPointerDown={(event) => {
        onPointerDown?.(event);
        wasOpen.current = open;
      }}
      onClick={(event) => {
        onClick?.(event);
        if (event.defaultPrevented || wasOpen.current) {
          wasOpen.current = false;
          return;
        }
        const { x, y } = cornerOf(event.currentTarget);
        // detail is 0 when Enter or Space pressed the button.
        openAt(x, y + 4, event.detail === 0);
      }}
      {...props}
    >
      {children ?? (
        <svg aria-hidden viewBox="0 0 16 16" fill="currentColor" className="size-4">
          <circle cx="3" cy="8" r="1.5" />
          <circle cx="8" cy="8" r="1.5" />
          <circle cx="13" cy="8" r="1.5" />
        </svg>
      )}
    </button>
  );
});

"use client";

export { type ContextMenuProps, ContextMenu } from "./context-menu-state";
export { type ContextMenuTargetProps, ContextMenuTarget, type ContextMenuButtonProps, ContextMenuButton } from "./context-menu-triggers";
export { type ContextMenuContentProps, ContextMenuContent } from "./context-menu-popup";
export { type ContextMenuItemProps, ContextMenuItem, ContextMenuGroup, ContextMenuGroupLabel, ContextMenuSeparator, ContextMenuShortcut, useContextMenu } from "./context-menu-items";
